// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface INowMeta {
    function owner() external view returns (address);
    function setMaxTxAmount(uint256 amount) external;
    function maxTxAmount() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xfac45d4b406D94cddFC48b198839673351CB2Bf9;
    address attacker = address(this);
    INowMeta nowMetaContract; // Renamed to avoid conflict

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed for this exploit
        // We'll just create the interface and get the owner
        nowMetaContract = INowMeta(TARGET);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get the current owner
        address contractOwner = nowMetaContract.owner();

        // Impersonate the owner and set maxTxAmount to 0
        vm.prank(contractOwner);
        nowMetaContract.setMaxTxAmount(0);

        // Verify the exploit worked
        uint256 newMaxTxAmount = nowMetaContract.maxTxAmount();
        assertEq(newMaxTxAmount, 0, "maxTxAmount should be 0 after owner abuse");
        assertEq(nowMetaContract.maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
